@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
  + IsOccupied : boolean
}

class Category {
  + Price : double
}

class StayType {
  + Description : string
}

class RestHome {}
class RestNursingHome {}
class ServiceFlat {}

class Inhabitant {
  + Name : string
  + IdentificationData : string
}

class Registration {
  + RegistrationDate : date
  + Status : string
}

class Assessment {
  + NeedsForHelp : string
  + RecommendedStayType : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + IsAccepted : boolean
  + IsValid : boolean
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + Amount : double
  + PaymentDate : datetime
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Category "1" -- "1" StayType

StayType <|-- RestHome
StayType <|-- RestNursingHome
StayType <|-- ServiceFlat

Inhabitant "1" -- "1..*" Stay
Inhabitant "1" -- "1" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "1" StayType

Stay "1" -- "1" Bed
Stay "1" -- "1" StayType

StayType "1" -- "0..*" WaitingList
WaitingList "1" -- "1..*" Inhabitant

Inhabitant "1" -- "0..*" Proposal
Proposal "1" -- "1" StayType
Proposal "1" -- "0..1" Inhabitant

Stay "1" -- "0..*" Invoice
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

